static uint32_t matrix_times(const uint32_t matrix[32], uint32_t vector)
{
    uint32_t result = 0;
    unsigned column = 0;

    while (vector != 0) {
        if (vector & 1u)
            result ^= matrix[column];
        vector >>= 1;
        column++;
    }
    return result;
}

uint32_t bfs_crc32_zeros(uint32_t initial, uint32_t length)
{
    uint32_t crc = ~initial;

    for (unsigned power = 0; length != 0; power++, length >>= 1) {
        if (length & 1u)
            crc = matrix_times(crc32_zero_advance[power], crc);
    }
    return ~crc;
}
